5	/**
6	 * Single source of truth for the fiscal-year rule shared across the owner pipeline and the
7	 * read-time {@code OwnerMapper}. The fiscal year starts on <strong>1 July</strong> and is
8	 * identified by the calendar year in which it <em>ends</em>: a date on or after 1 July belongs to
9	 * the fiscal year named for the following calendar year, while a date in January-June belongs to
10	 * the fiscal year named for its own calendar year (e.g. 2026-07-01 and 2027-06-30 are both
11	 * {@code FY27}; 2026-06-30 is {@code FY26}).
12	 *
13	 * <p>Centralised here (as {@link BusinessDay} is for the business-day roll) so every date-derived
14	 * value agrees on one definition: {@link AssignMembershipNumber} builds the membership number's
15	 * year segment from it, while {@code OwnerMapper} derives the exposed {@code fiscalYear} label and
16	 * counts tenure in elapsed fiscal years from it. Callers pass the already business-day-adjusted
17	 * {@code registrationDate} the pipeline stored, so the fiscal year follows the adjusted date.
18	 */
19	public final class FiscalYear {
20	
21	    /** The month the fiscal year starts on (1 July). */
22	    private static final int FISCAL_START_MONTH = 7;
23	
24	    private FiscalYear() {
25	    }
26	
27	    /**
28	     * The fiscal year containing {@code date}, identified by the calendar year in which it ends: the
29	     * date's own year when the date falls before 1 July, otherwise the following year.
30	     */
31	    public static int of(LocalDate date) {
32	        return date.getMonthValue() >= FISCAL_START_MONTH ? date.getYear() + 1 : date.getYear();
33	    }
34	
35	    /**
36	     * The last two digits of the fiscal year containing {@code date}, zero-padded (e.g. {@code 27}
37	     * for a fiscal year of 2027, {@code 09} for 2009). Shared so every {@code <prefix><YY>} rendering
38	     * of the fiscal year (the {@code FY<YY>} label, the membership number's {@code M<YY>} segment)
39	     * derives its year segment the same way.
40	     */
41	    public static String yy(LocalDate date) {
42	        return String.format("%02d", of(date) % 100);
43	    }
44	
45	    /**
46	     * The {@code FY<YY>} label for the fiscal year containing {@code date}, where {@code YY} is the
47	     * last two digits of the fiscal year (e.g. {@code FY27}).
48	     */
49	    public static String label(LocalDate date) {
50	        return "FY" + yy(date);
51	    }
52	
53	    /**
54	     * The number of whole fiscal years elapsed between {@code from} and {@code to}: the difference
55	     * between the fiscal year of each date, i.e. the count of 1-July boundaries crossed. Returns 0
56	     * when {@code to} is not after {@code from}.
57	     */
58	    public static long elapsed(LocalDate from, LocalDate to) {
59	        return Math.max(of(to) - of(from), 0);
60	    }
61	}
