10	/**
11	 * De-duplicates the owner's {@code customerCode} against the codes already in the data store.
12	 * {@link AssignCustomerCode} derives the code deterministically from the owner's own fields, so two
13	 * distinct owners can in principle collide. When the assigned code matches an existing owner's
14	 * {@code customerCode}, this step finds the smallest {@code n} of 2 or more that makes it unique and
15	 * applies {@link OwnerCustomerCode#withSuffix} (e.g. {@code NSW-1A2B3C4D} → {@code NSW-1A2B3C4D-2}).
16	 * The suffix spelling lives in {@link OwnerCustomerCode}, which owns the {@code customerCode} format;
17	 * this step contributes only the orchestration — gather existing codes, pick a free {@code n}.
18	 *
19	 * <p>Runs within the create transaction after {@link AssignCustomerCode} and before
20	 * {@link AssignMembershipNumber}, so the membership number and every other value derived from the
21	 * code see the de-duplicated value. The owner being created has not been saved yet, so it is not
22	 * among the existing codes compared against.
23	 */
24	public class DeduplicateCustomerCode {
25	
26	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
27	        String base = owner.getCustomerCode();
28	        Set<String> existing = new HashSet<>();
29	        for (Owner other : ownerRepository.findAll()) {
30	            existing.add(other.getCustomerCode());
31	        }
32	        if (!existing.contains(base)) {
33	            return;
34	        }
35	        int n = 2;
36	        String candidate;
37	        do {
38	            candidate = OwnerCustomerCode.withSuffix(base, n);
39	            n++;
40	        }
41	        while (existing.contains(candidate));
42	        owner.setCustomerCode(candidate);
43	    }
44	}
