1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "selfLink",
22	        expression = "java(\"/api/owners/\" + owner.getId())")
23	    @Mapping(target = "displayName",
24	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
25	    @Mapping(target = "initials",
26	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
27	            + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
28	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
29	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
30	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
31	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
32	    @Mapping(target = "locality", expression = "java(locality(owner))")
33	    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
34	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
35	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
36	    @Mapping(target = "bulkSignupWarning", expression = "java(bulkSignupWarning(owner))")
37	    @Mapping(target = "capacityWarning", expression = "java(capacityWarning(owner))")
38	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
39	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
40	    @Mapping(target = "identityKey",
41	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.of(owner))")
42	    @Mapping(target = "telephoneDisplay",
43	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerTelephone.toDisplay(owner.getTelephone()))")
44	    OwnerDto toOwnerDto(Owner owner);
45	
46	    /**
47	     * Derives the owner's salutation at read time: the stored {@code title} followed by a single
48	     * space and the {@code lastName} when a title was supplied, otherwise just the {@code lastName}.
49	     */
50	    default String salutation(Owner owner) {
51	        String title = owner.getTitle();
52	        if (title == null || title.isBlank()) {
53	            return owner.getLastName();
54	        }
55	        return title + " " + owner.getLastName();
56	    }
57	
58	    /**
59	     * Derives the owner's preferred contact channel at read time: {@code EMAIL} when an email is
60	     * present, otherwise {@code PHONE}.
61	     */
62	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
63	        return hasEmail(owner) ? OwnerDto.ContactPreferenceEnum.EMAIL
64	            : OwnerDto.ContactPreferenceEnum.PHONE;
65	    }
66	
67	    /**
68	     * Derives the owner's age band at read time from {@code birthDate}, computed against
69	     * {@code registrationDate} (falling back to the current date when none is stored):
70	     * {@code MINOR} when under 18, {@code ADULT} when 18-64, {@code SENIOR} when 65 or older.
71	     * Returns {@code null} when no birth date was supplied, so the field is absent for owners
72	     * created without one.
73	     */
74	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
75	        java.time.LocalDate birthDate = owner.getBirthDate();
76	        if (birthDate == null) {
77	            return null;
78	        }
79	        java.time.LocalDate asOf = owner.getRegistrationDate() != null
80	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
81	        int age = java.time.Period.between(birthDate, asOf).getYears();
82	        if (age < 18) {
83	            return OwnerDto.AgeBandEnum.MINOR;
84	        }
85	        if (age < 65) {
86	            return OwnerDto.AgeBandEnum.ADULT;
87	        }
88	        return OwnerDto.AgeBandEnum.SENIOR;
89	    }
90	
91	    /** Whether the owner has a non-blank email address. */
92	    default boolean hasEmail(Owner owner) {
93	        return owner.getEmail() != null && !owner.getEmail().isBlank();
94	    }
95	
96	    /**
97	     * Reports the owner's bulk-signup warning: {@code true} when more than 80 owners had already
98	     * been created on this owner's registration business day at the time it was created. Treats a
99	     * missing value (owners created before this rule existed) as {@code false}.
100	     */
101	    default boolean bulkSignupWarning(Owner owner) {
102	        return Boolean.TRUE.equals(owner.getBulkSignupWarning());
103	    }
104	
105	    /**
106	     * Reports the owner's capacity warning: {@code true} when this owner's city already held
107	     * between 40 and 49 owners (approaching the per-city hard limit of 50) at the time this owner
108	     * was created. Treats a missing value (owners created before this rule existed) as
109	     * {@code false}.
110	     */
111	    default boolean capacityWarning(Owner owner) {
112	        return Boolean.TRUE.equals(owner.getCapacityWarning());
113	    }
114	
115	    /**
116	     * Computes the owner's check digit: a single Luhn check digit (0-9) over the digits contained
117	     * in {@code customerCode}, derived at read time. Returns {@code null} when no customer code has
118	     * been assigned.
119	     */
120	    default Integer checkDigit(Owner owner) {
121	        String customerCode = owner.getCustomerCode();
122	        if (customerCode == null) {
123	            return null;
124	        }
125	        int sum = 0;
126	        boolean dbl = true;
127	        for (int i = customerCode.length() - 1; i >= 0; i--) {
128	            char c = customerCode.charAt(i);
129	            if (c < '0' || c > '9') {
130	                continue;
131	            }
132	            int d = c - '0';
133	            if (dbl) {
134	                d *= 2;
135	                if (d > 9) {
136	                    d -= 9;
137	                }
138	            }
139	            sum += d;
140	            dbl = !dbl;
141	        }
142	        return (10 - (sum % 10)) % 10;
143	    }
144	
145	    /**
146	     * Derives the owner's membership points: starts at 0, adds 2 when an email is present, adds 1
147	     * when the owner had no namesakes at creation ({@code namesakeCount == 0}), adds 2 when the
148	     * owner belongs to a household of 3 or more members ({@code householdSize >= 3}, counted at
149	     * creation by {@code AssignHouseholdSize}), and adds 3 when the owner's tenure is at least one
150	     * elapsed fiscal year (fiscal years start 1 July) since its {@code registrationDate}.
151	     */
152	    default int membershipPoints(Owner owner) {
153	        int points = 0;
154	        if (hasEmail(owner)) {
155	            points += 2;
156	        }
157	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
158	            points += 1;
159	        }
160	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
161	            points += 2;
162	        }
163	        if (tenureFiscalYears(owner) >= 1) {
164	            points += 3;
165	        }
166	        return points;
167	    }
168	
169	    /**
170	     * Maps the owner's {@link #membershipPoints(Owner) membership points} to a numeric level:
171	     * level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more, then applies the
172	     * household level ceiling (see {@link #uncappedMembershipLevel(Owner)}).
173	     *
174	     * <p>When a {@code membershipLevelCap} was recorded at creation time (by
175	     * {@code CapMembershipLevel}, as one above the maximum level among the owner's existing
176	     * household members), the level is clamped down to that cap. With no cap stored (no existing
177	     * household member when the owner was created) the uncapped level is returned unchanged.
178	     */
179	    default int membershipLevel(Owner owner) {
180	        int level = uncappedMembershipLevel(owner);
181	        Integer cap = owner.getMembershipLevelCap();
182	        if (cap != null && level > cap) {
183	            return cap;
184	        }
185	        return level;
186	    }
187	
188	    /**
189	     * The owner's membership level derived purely from its {@link #membershipPoints(Owner) points},
190	     * before the household level ceiling is applied: level 1 for 0-1 points, 2 for 2-3, 3 for 4-5,
191	     * and 4 for 6 or more.
192	     */
193	    default int uncappedMembershipLevel(Owner owner) {
194	        int points = membershipPoints(owner);
195	        if (points <= 1) {
196	            return 1;
197	        }
198	        if (points <= 3) {
199	            return 2;
200	        }
201	        if (points <= 5) {
202	            return 3;
203	        }
204	        return 4;
205	    }
206	
207	    /**
208	     * The owner's tenure in whole elapsed fiscal years (fiscal years start 1 July): the number of
209	     * 1-July boundaries between its {@code registrationDate} and today, derived via
210	     * {@code FiscalYear} so it matches the fiscal year the membership number and {@code fiscalYear}
211	     * label use. Returns 0 when no registration date is stored (or it lies in the future), so an
212	     * owner with no recorded tenure never qualifies for the tenure-gated points.
213	     */
214	    default long tenureFiscalYears(Owner owner) {
215	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
216	        if (registrationDate == null) {
217	            return 0;
218	        }
219	        return org.springframework.samples.petclinic.rest.function.owner.FiscalYear
220	            .elapsed(registrationDate, java.time.LocalDate.now());
221	    }
222	
223	    /**
224	     * The owner's {@code fiscalYear} label, {@code FY<YY>} for the fiscal year (starting 1 July)
225	     * that contains its business-day-adjusted {@code registrationDate}, derived via
226	     * {@code FiscalYear}. Returns {@code null} when no registration date is stored, so the field is
227	     * absent for such owners.
228	     */
229	    default String fiscalYear(Owner owner) {
230	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
231	        if (registrationDate == null) {
232	            return null;
233	        }
234	        return org.springframework.samples.petclinic.rest.function.owner.FiscalYear.label(registrationDate);
235	    }
236	
237	    /**
238	     * Derives the owner's locality (region) at read time from the region-and-hash
239	     * {@code customerCode}: its {@code REGION} prefix (e.g. {@code NSW} for {@code NSW-1A2B3C4D}),
240	     * so the region cannot drift from the identity every other derived value flows through. Owners
241	     * with no {@code customerCode} fall back to resolving the region directly. Both the parse and
242	     * the fallback (including the {@code UNKNOWN} sentinel) live in {@code OwnerCustomerCode}.
243	     */
244	    default String locality(Owner owner) {
245	        String region = org.springframework.samples.petclinic.rest.function.owner.OwnerCustomerCode
246	            .regionOf(owner.getCustomerCode());
247	        return region != null ? region
248	            : org.springframework.samples.petclinic.rest.function.owner.OwnerCustomerCode
249	                .regionFor(owner);
250	    }
251	
252	    /**
253	     * Derives the owner's segment at read time, formatted {@code <TIER>_<AREA>}: one of
254	     * {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL}, {@code STANDARD_METRO} or
255	     * {@code STANDARD_REGIONAL}. TIER is {@code PREMIUM} when the {@link #membershipLevel(Owner)
256	     * membership level} is 3 or more, otherwise {@code STANDARD}. AREA is {@code METRO} when the
