3	import java.util.concurrent.atomic.AtomicLong;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.slf4j.Logger;
7	import org.slf4j.LoggerFactory;
8	import org.springframework.samples.petclinic.mapper.OwnerMapper;
9	import org.springframework.samples.petclinic.model.Owner;
10	
11	/**
12	 * Emits the owner-created audit trail to the dedicated {@code AUDIT} logger once a new owner has
13	 * been persisted. Two things are emitted:
14	 * <ul>
15	 *   <li>a human-readable line recording the assigned owner id, the region-and-hash
16	 *       {@code customerCode}, {@code registrationDate}, the derived {@code membershipLevel} and the
17	 *       assigned {@code membershipNumber};</li>
18	 *   <li>an immutable structured {@link OwnerCreatedEvent} (as JSON), tagged with a monotonically
19	 *       increasing {@link #SEQUENCE sequence} across creates and carrying the owner's current
20	 *       primary identifier.</li>
21	 * </ul>
22	 *
23	 * <p>Runs after {@link SaveOwner}, so the generated id is available.
24	 */
25	public class AuditOwnerCreated {
26	
27	    private static final Logger logger = LoggerFactory.getLogger("AUDIT");
28	
29	    /** Monotonically increasing sequence shared across all creates (and function instances). */
30	    private static final AtomicLong SEQUENCE = new AtomicLong();
31	
32	    public void service(@Val Owner owner, OwnerMapper ownerMapper) {
33	        int membershipLevel = ownerMapper.membershipLevel(owner);
34	        logger.info("Owner created: id={} customerCode={} registrationDate={} "
35	                + "membershipLevel={} membershipNumber={}",
36	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
37	                membershipLevel, owner.getMembershipNumber());
38	
39	        // The current primary identifier is the customerCode; a later unification into memberId
40	        // changes only this argument (and OwnerCreatedEvent's field), not this step's shape.
41	        OwnerCreatedEvent event = new OwnerCreatedEvent(SEQUENCE.incrementAndGet(),
42	                owner.getId(), owner.getCustomerCode(), membershipLevel);
43	        logger.info(event.toJson());
44	    }
45	}
