1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * Immutable structured event emitted to the {@code AUDIT} logger when a new owner is created,
5	 * alongside the human-readable audit line (see {@link AuditOwnerCreated}). Serialised as the JSON
6	 * object {@code {seq, ownerId, customerCode, membershipLevel, event}} with
7	 * {@code event == }{@value #EVENT}.
8	 *
9	 * <p>{@code seq} is a monotonically increasing sequence across creates (assigned by
10	 * {@link AuditOwnerCreated}), so consumers can order and de-duplicate events independently of log
11	 * timestamps.
12	 *
13	 * <p>The {@code customerCode} field carries the owner's <em>current primary identifier</em>. Today
14	 * that is the region-and-hash {@code customerCode} ({@link OwnerCustomerCode}); when the identity is
15	 * later unified into a {@code memberId}, this single field is what switches to carry the
16	 * {@code memberId} instead — the record is the one place that definition lives.
17	 *
18	 * <p>Being a record, the event is deeply immutable once constructed.
19	 */
20	public record OwnerCreatedEvent(long seq, int ownerId, String customerCode, int membershipLevel) {
21	
22	    /** The {@code event} discriminator carried by every owner-created event. */
23	    public static final String EVENT = "OWNER_CREATED";
24	
25	    /**
26	     * The canonical JSON form {@code {seq, ownerId, customerCode, membershipLevel, event}}. Built
27	     * directly rather than via a mapper so the audit side-effect carries no dependency on the HTTP
28	     * response serialisation.
29	     */
30	    public String toJson() {
31	        return "{\"seq\":" + this.seq
32	                + ",\"ownerId\":" + this.ownerId
33	                + ",\"customerCode\":" + quote(this.customerCode)
34	                + ",\"membershipLevel\":" + this.membershipLevel
35	                + ",\"event\":\"" + EVENT + "\"}";
36	    }
37	
38	    /** A JSON string literal for {@code value}, escaping the characters JSON requires, or {@code null}. */
39	    private static String quote(String value) {
40	        if (value == null) {
41	            return "null";
42	        }
43	        StringBuilder sb = new StringBuilder(value.length() + 2).append('"');
44	        for (int i = 0; i < value.length(); i++) {
45	            char c = value.charAt(i);
46	            switch (c) {
47	                case '"' -> sb.append("\\\"");
48	                case '\\' -> sb.append("\\\\");
49	                case '\n' -> sb.append("\\n");
50	                case '\r' -> sb.append("\\r");
51	                case '\t' -> sb.append("\\t");
52	                default -> {
53	                    if (c < 0x20) {
54	                        sb.append(String.format("\\u%04x", (int) c));
55	                    }
56	                    else {
57	                        sb.append(c);
58	                    }
59	                }
60	            }
61	        }
62	        return sb.append('"').toString();
63	    }
64	}
