3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	/**
8	 * Shared SHA-256 hex encoding for the {@code POST /owners} pipeline. Both the owner
9	 * {@link OwnerIdentity identityKey} (full, lower-case) and the {@link OwnerHousehold} household id
10	 * (first 12 characters, upper-cased) are the hex digest of a composed string; this centralises the
11	 * digest-and-encode mechanism so those callers choose only the case/length they want rather than
12	 * each re-implementing it.
13	 */
14	final class Sha256 {
15	
16	    private static final char[] LOWER_HEX = "0123456789abcdef".toCharArray();
17	
18	    private Sha256() {
19	    }
20	
21	    /** The lower-case hex SHA-256 of the UTF-8 bytes of {@code value}. */
22	    static String hex(String value) {
23	        byte[] digest = digest(value);
24	        StringBuilder sb = new StringBuilder(digest.length * 2);
25	        for (byte b : digest) {
26	            sb.append(LOWER_HEX[(b >> 4) & 0xF]).append(LOWER_HEX[b & 0xF]);
27	        }
28	        return sb.toString();
29	    }
30	
31	    private static byte[] digest(String value) {
32	        try {
33	            return MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
34	        }
35	        catch (NoSuchAlgorithmException ex) {
36	            throw new IllegalStateException("SHA-256 not available", ex);
37	        }
38	    }
39	}
