package org.springframework.samples.petclinic.rest.function.owner;

import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Single source of truth for the owner telephone normalisation rule used across the
 * {@code POST /owners} pipeline: a telephone is canonicalised to E.164 form. Both
 * {@link NormalizeOwnerTelephone} (which stores the canonical value and rejects an input that
 * cannot form one) and {@link OwnerIdentity} (which folds the canonical value into the identity
 * key) must agree on this definition, so it lives here rather than being re-implemented at each
 * site.
 *
 * <p>The rule: strip spaces, dashes and brackets; keep a leading {@code '+'} and country code
 * when present, otherwise assume country code {@code +61} and drop a single leading {@code '0'}
 * from the national digits; the result must be a {@code '+'} followed by 8 to 15 digits. So
 * {@code "0412 345 678"} canonicalises to {@code "+61412345678"} and {@code "+64 21 123 456"}
 * to {@code "+6421123456"}.
 *
 * <p>In addition, where the country code has a known fixed national-number length, the national
 * part (the digits after the country code) must have exactly that length: {@code +61} requires
 * 9 national digits and {@code +1} requires 10. A number whose national part is the wrong length
 * for its country is not a valid E.164 number here and is rejected. Country codes without a
 * listed rule keep only the general 8-to-15-digit total check.
 */
public final class OwnerTelephone {

    /**
     * Country code (without the leading {@code '+'}) to its required national-number length.
     * Ordered longest-prefix-first so a number is matched against {@code 61} before {@code 1}.
     */
    private static final Map<String, Integer> NATIONAL_LENGTHS = new LinkedHashMap<>();

    static {
        NATIONAL_LENGTHS.put("61", 9);
        NATIONAL_LENGTHS.put("1", 10);
    }

    private OwnerTelephone() {
    }

    /**
     * Canonicalise {@code telephone} to E.164 form, or return {@code null} when it cannot form a
     * valid E.164 number (null/blank input, a non-digit left after stripping separators, fewer
     * than 8 or more than 15 digits after the {@code '+'}, or a national part whose length is
     * wrong for a country code with a known fixed length — {@code +61} => 9, {@code +1} => 10).
     */
    static String toE164(String telephone) {
        if (telephone == null) {
            return null;
        }
        // Strip spaces, dashes and brackets, leaving an optional leading '+' and the digits.
        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
        String digits;
        if (cleaned.startsWith("+")) {
            // Leading '+' and country code present: keep as-is.
            digits = cleaned.substring(1);
        } else {
            // No country code: assume +61 and drop a single leading '0' from the national digits.
            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
            digits = "61" + national;
        }
        if (!digits.matches("[0-9]{8,15}")) {
            return null;
        }
        // Enforce the per-country national-number length where one is known.
        for (Map.Entry<String, Integer> rule : NATIONAL_LENGTHS.entrySet()) {
            String countryCode = rule.getKey();
            if (digits.startsWith(countryCode)) {
                int nationalLength = digits.length() - countryCode.length();
                if (nationalLength != rule.getValue()) {
                    return null;
                }
                break;
            }
        }
        return "+" + digits;
    }

    /**
     * Best-effort canonical form of {@code telephone}: its E.164 form ({@link #toE164(String)})
     * when it forms one, otherwise the raw value unchanged (and the empty string when null). Used
     * where a stable string is needed even for a value that is not a valid E.164 number — folding
     * the telephone into the owner identity key ({@link OwnerIdentity}) and into the identity's
     * hash ({@code OwnerCustomerCode}) — so that fallback policy lives here alongside the rule it
     * builds on rather than being reimplemented at each site.
     */
    static String toE164OrRaw(String telephone) {
        String e164 = toE164(telephone);
        return e164 != null ? e164 : (telephone == null ? "" : telephone);
    }

    /**
     * Human-readable form of a stored E.164 {@code telephone}: the country code, a space, then
     * the national digits grouped in threes (e.g. {@code "+61412345678"} => {@code "+61 412 345
     * 678"}). The country code is identified from {@link #NATIONAL_LENGTHS}, longest-prefix-first
     * (so {@code 61} matches before {@code 1}). Null in gives null out; a value that is not a
     * recognisable E.164 number (cannot be canonicalised, or whose country code is not one we
     * list) is returned unchanged, so the display is always best-effort rather than throwing.
     */
    public static String toDisplay(String telephone) {
        if (telephone == null) {
            return null;
        }
        String e164 = toE164(telephone);
        if (e164 == null) {
            return telephone;
        }
        String digits = e164.substring(1); // drop the leading '+'
        String countryCode = null;
        for (String code : NATIONAL_LENGTHS.keySet()) {
            if (digits.startsWith(code)) {
                countryCode = code;
                break;
            }
        }
        if (countryCode == null) {
            return e164;
        }
        String national = digits.substring(countryCode.length());
        StringBuilder sb = new StringBuilder("+").append(countryCode);
        for (int i = 0; i < national.length(); i += 3) {
            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
        }
        return sb.toString();
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Create-time capacity guard for {@code POST /owners}: rejects a request whose city already
 * contains 50 or more owners, with a 409 via {@link CityAtCapacityException}.
 *
 * <p>The city is compared case-insensitively against each existing owner's city (as in
 * {@link AssignCustomerCode}), so the count is independent of letter case. Runs before
 * {@link BuildOwner}.
 */
public class CheckOwnerCityCapacity {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws CityAtCapacityException {
        String city = request.getCity();
        if (CityCapacity.countOwnersIn(city, ownerRepository) >= CityCapacity.CAPACITY) {
            throw new CityAtCapacityException(city);
        }
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.time.DayOfWeek;
import java.time.LocalDate;
import java.util.Set;

import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Single source of truth for the business-day rule on an owner's registration date: the
 * effective registration date must fall on a business day, so a Saturday or Sunday rolls
 * forward to the following Monday. A date that is already a weekday is returned unchanged.
 *
 * <p>A business day is additionally not one of the fixed public holidays, so a date landing on a
 * listed holiday also rolls forward to the next non-holiday business day.
 *
 * <p>Centralised here so every site agrees on one definition: {@link BuildOwner} stores the
 * adjusted date on the owner (and everything derived from it, such as the membership number's
 * year segment in {@link AssignMembershipNumber}, then uses the adjusted value), while
 * {@link CheckDailyOwnerLimit} counts existing owners against the same adjusted business day.
 */
final class BusinessDay {

    /** Fixed public holidays that are not business days; a date landing here rolls forward. */
    private static final Set<LocalDate> HOLIDAYS = Set.of(
        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"), LocalDate.parse("2026-04-25"),
        LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));

    private BusinessDay() {
    }

    /**
     * Rolls {@code date} forward to the next business day: a Saturday, Sunday or listed public
     * holiday advances a day until a non-holiday weekday is reached; such a weekday is returned
     * unchanged.
     */
    static LocalDate rollForward(LocalDate date) {
        LocalDate rolled = date;
        while (rolled.getDayOfWeek() == DayOfWeek.SATURDAY || rolled.getDayOfWeek() == DayOfWeek.SUNDAY
                || HOLIDAYS.contains(rolled)) {
            rolled = rolled.plusDays(1);
        }
        return rolled;
    }

    /**
     * Counts existing owners whose stored {@code registrationDate} equals {@code businessDay} — the
     * single definition of "owners created on this business day" shared by the create-time rules
     * ({@link CheckDailyOwnerLimit}'s hard cap and {@link AssignBulkSignupWarning}'s flag), so they
     * can never drift apart. Both call this and compare the result against their own threshold.
     */
    static long countOwnersOn(LocalDate businessDay, OwnerRepository ownerRepository) {
        return ownerRepository.findAll().stream()
            .map(Owner::getRegistrationDate)
            .filter(businessDay::equals)
            .count();
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Household assignment for {@code POST /owners}. The owner's {@code householdId} is
 * <em>deterministic</em>: it is derived from {@code (lastName, postcode)} alone (see
 * {@link OwnerHousehold#deriveId}), so every owner that shares a last name and postcode derives the
 * same id automatically — there is no longer any explicit linking of existing owners. Owners with
 * no postcode belong to no household and are left with a null {@code householdId}.
 *
 * <p>Runs within the create transaction (after {@link BuildOwner}/{@link AssignCustomerCode},
 * before {@link SaveOwner}). Sharing a household is no longer a duplicate: several members may
 * belong to the same household as long as their identity keys differ (see
 * {@link CheckOwnerIdentityUnique}). The id assigned here is purely a function of
 * {@code (lastName, postcode)} and is what {@link CapMembershipLevel} later uses to find the
 * household's existing members.
 */
public class AssignHousehold {

    public void service(@Val Owner owner) {
        owner.setHouseholdId(OwnerHousehold.deriveId(owner));
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

/**
 * Single source of truth for the fiscal-year rule shared across the owner pipeline and the
 * read-time {@code OwnerMapper}. The fiscal year starts on <strong>1 July</strong> and is
 * identified by the calendar year in which it <em>ends</em>: a date on or after 1 July belongs to
 * the fiscal year named for the following calendar year, while a date in January-June belongs to
 * the fiscal year named for its own calendar year (e.g. 2026-07-01 and 2027-06-30 are both
 * {@code FY27}; 2026-06-30 is {@code FY26}).
 *
 * <p>Centralised here (as {@link BusinessDay} is for the business-day roll) so every date-derived
 * value agrees on one definition: {@link AssignMembershipNumber} builds the membership number's
 * year segment from it, while {@code OwnerMapper} derives the exposed {@code fiscalYear} label and
 * counts tenure in elapsed fiscal years from it. Callers pass the already business-day-adjusted
 * {@code registrationDate} the pipeline stored, so the fiscal year follows the adjusted date.
 */
public final class FiscalYear {

    /** The month the fiscal year starts on (1 July). */
    private static final int FISCAL_START_MONTH = 7;

    private FiscalYear() {
    }

    /**
     * The fiscal year containing {@code date}, identified by the calendar year in which it ends: the
     * date's own year when the date falls before 1 July, otherwise the following year.
     */
    public static int of(LocalDate date) {
        return date.getMonthValue() >= FISCAL_START_MONTH ? date.getYear() + 1 : date.getYear();
    }

    /**
     * The last two digits of the fiscal year containing {@code date}, zero-padded (e.g. {@code 27}
     * for a fiscal year of 2027, {@code 09} for 2009). Shared so every {@code <prefix><YY>} rendering
     * of the fiscal year (the {@code FY<YY>} label, the membership number's {@code M<YY>} segment)
     * derives its year segment the same way.
     */
    public static String yy(LocalDate date) {
        return String.format("%02d", of(date) % 100);
    }

    /**
     * The {@code FY<YY>} label for the fiscal year containing {@code date}, where {@code YY} is the
     * last two digits of the fiscal year (e.g. {@code FY27}).
     */
    public static String label(LocalDate date) {
        return "FY" + yy(date);
    }

    /**
     * The number of whole fiscal years elapsed between {@code from} and {@code to}: the difference
     * between the fiscal year of each date, i.e. the count of 1-July boundaries crossed. Returns 0
     * when {@code to} is not after {@code from}.
     */
    public static long elapsed(LocalDate from, LocalDate to) {
        return Math.max(of(to) - of(from), 0);
    }
}

